# minimax-pmoves.sh -- launch `minimax` with pmoves/env.shared loaded
# ===========================================================================
# Auto-generated wrapper for minimax-pmoves. Mirrors the hand-written
# claude-pmoves.sh / crush-pmoves.sh SHELL pattern (resolve repo root via
# symlink-walk, source env.shared, exec the binary) so every pmoves_wrapper
# has the same Windows + POSIX entry surface and the same env-loaded
# preconditions.  The hand-written launchers carry SDK-fixed FAIL-CLOSED
# MCP roster logic this template does not reproduce -- that is by design.
#
# Usage:
#   bash deploy/provision/minimax-pmoves.sh        [args...]
#   install-minimax-pmoves-pmoves-command.sh && minimax-pmoves         # rc function
#   minimax-pmoves.cmd                              # Windows Explorer double-click
#
# Purpose: MiniMax Code with the pmoves.bootstrap/v1 client profile (roster + service tags + routing + constraints)
#
# Override env.shared path with PMOVES_ENV_SHARED.
set -u

# --- REPO-ROOT RESOLUTION (mirror claude-pmoves.sh) -------------------------
# See test-launcher-root-resolution.sh for why this walk must stay byte-
# identical across every launcher that carries it: an installer symlink at
# ~/.local/bin/<name> would otherwise make ROOT=$HOME and env.shared miss.
SELF="${BASH_SOURCE[0]:-$0}"
while [ -L "$SELF" ]; do
  link_dir="$(CDPATH='' cd -P -- "$(dirname -- "$SELF")" && pwd)"
  SELF="$(readlink -- "$SELF")"
  case "$SELF" in /*) ;; *) SELF="$link_dir/$SELF" ;; esac
done
SELF_DIR="$(CDPATH='' cd -P -- "$(dirname -- "$SELF")" && pwd)"
if [ -n "${PMOVES_LAUNCHER_ROOT:-}" ]; then
  ROOT="$PMOVES_LAUNCHER_ROOT"
else
  ROOT="$(CDPATH='' cd -P -- "$SELF_DIR/../.." && pwd)" || ROOT=""
fi
if [ ! -f "${ROOT:-/nonexistent}/pmoves/Makefile" ]; then
  if [ -n "${PMOVES_ENV_SHARED:-}" ] && [ -f "$PMOVES_ENV_SHARED" ]; then
    echo "[minimax-pmoves] WARN: repo root not found (${ROOT:-<unresolved>}); using PMOVES_ENV_SHARED." >&2
  else
    echo "[minimax-pmoves] ERROR: no pmoves/Makefile under repo root: ${ROOT:-<unresolved>}" >&2
    echo "[minimax-pmoves]        (resolved from: $SELF)" >&2
    exit 1
  fi
fi

# --- MAVIS SDK ENV STRIP ---------------------------------------------------
# The Mavis SDK's `env` block in `~/.claude/settings.json` injects
# ANTHROPIC_BASE_URL, ANTHROPIC_AUTH_TOKEN, ANTHROPIC_MODEL, MCP_TIMEOUT,
# API_TIMEOUT_MS, CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC, ... into every
# Claude Code session's process env.  That env block is inherited by the
# shell that runs this launcher, and would otherwise be inherited by the
# launched `minimax` -- overriding the operator's own CLI settings
# (their API endpoint, their model picker).
#
# The strip checks each Mavis SDK var against `minimax`'s NEEDS list
# (defined in pmoves/scripts/mavis_sdk_env.sh alongside this comment):
#   * keeps the ones `minimax` consumes
#   * preserves the others under PMOVES_MAVIS_SDK_<NAME> for inspection
#   * unsets the originals
#   * emits one WARN line summarizing what was caught
#
# Sourced AFTER repo-root resolution (helper file is repo-relative) and
# BEFORE env.shared loading (the env.shared reader below has a parallel
# blocklist for env.shared itself; the two layers cover the SHELL env and
# env.shared independently).
# ---------------------------------------------------------------------------
if [ -f "$ROOT/pmoves/scripts/mavis_sdk_env.sh" ]; then
  # shellcheck source=../../pmoves/scripts/mavis_sdk_env.sh
  . "$ROOT/pmoves/scripts/mavis_sdk_env.sh"
  mavis_sdk_strip_env_for "minimax"
else
  echo "[minimax-pmoves] WARN: mavis_sdk_env.sh not found at $ROOT/pmoves/scripts/ -- Mavis SDK env may bleed into the launched session." >&2
fi

# --- ENV.SHARED LOADING (mirror claude-pmoves.sh :: lines 72-127) -----------
# env.shared is Docker Compose env_file format: unquoted values + ALIAS lines
# like `SUPABASE_SERVICE_ROLE_KEY=${SERVICE_ROLE_KEY}`.  Two hazards:
#   1. We can't `source` it raw -- unquoted values break `. file`.
#   2. We must NOT export values verbatim -- that leaks the literal string
#      "${SERVICE_ROLE_KEY}" into MCP headers and starts them unauthorized.
# Build a sanitized assignment file (single-quote plain values; pass ${...}-
# bearing lines through for shell expansion), then source it auto-export.
ENVF="${PMOVES_ENV_SHARED:-$ROOT/pmoves/env.shared}"
if [ -f "$ENVF" ]; then
  blocklist='^(ANTHROPIC_API_KEY|ANTHROPIC_AUTH_TOKEN|ANTHROPIC_BASE_URL|MINIMAX_API_KEY)$'
  set +H 2>/dev/null || true
  tmpf=$(mktemp)
  n=0
  while IFS= read -r line || [ -n "$line" ]; do
    line="${line%$'\r'}"
    case "$line" in ''|\#*) continue;; esac
    case "$line" in *=*) : ;; *) continue;; esac
    key=${line%%=*}
    val=${line#*=}
    key=$(printf '%s' "$key" | tr -d '[:space:]')
    [ -z "$key" ] && continue
    if [[ "$key" =~ $blocklist ]]; then continue; fi
    val="${val#"${val%%[![:space:]]*}"}"
    # Two-pass expansion: pass literal `${...}` lines through verbatim
    # so the shell expands them on `. "$tmpf"`.  Otherwise single-quote
    # so the literal value lands in the env (avoid the placeholder leak
    # Codex #1987 P2 caught).  Mirror pmoves/scripts/with-env.sh.
    #
    # Single-quote escape routes through awk octal (\047) -- never nest
    # `\''` literals (loses count in f-string backslash escapes; see
    # PR conversation 2026-09-16 + pmoves_launcher_generator_LEARNINGS.md).
    if printf '%s' "$val" | grep -qE '[$]{'; then
      printf '%s=%s\n' "$key" "$val" >> "$tmpf"
    else
      esc=$(printf '%s' "$val" | awk '{ gsub(/\047/, "\047\\\047\047"); print }')
      printf "%s='%s'\n" "$key" "$esc" >> "$tmpf"
    fi
    n=$((n+1))
  done < "$ENVF"
  set -a; set +u
  . "$tmpf"
  set +a; set -u
  rm -f "$tmpf"
  set -H 2>/dev/null || true
  echo "[minimax-pmoves] loaded $n vars from $ENVF" >&2
else
  echo "[minimax-pmoves] WARN: $ENVF not found -- MCP creds may be missing." >&2
  echo "[minimax-pmoves]       run: make -C pmoves ensure-env-shared" >&2
fi

# --- HOST TLS ------------------------------------------------------------
# env.shared carries SSL_CERT_FILE= / SSL_CERT_DIR= / REQUESTS_CA_BUNDLE= ...
# EMPTY on purpose (a container leak guard), and the loader above EXPORTS
# them. On the host, set-but-empty breaks python ssl and the HF Xet backend
# (CERTIFICATE_VERIFY_FAILED). Clear the empties; fill in the system bundle
# only when no CA variable is configured by a later-loaded env file.
# See pmoves/scripts/pm-ca-bundle.sh.
if [ -f "$ROOT/pmoves/scripts/pm-ca-bundle.sh" ]; then
  # shellcheck source=../../pmoves/scripts/pm-ca-bundle.sh
  . "$ROOT/pmoves/scripts/pm-ca-bundle.sh"
  pm_ca_bundle_normalize || true
  if [ -n "${PM_CA_BUNDLE_LINE:-}" ]; then
    echo "[minimax-pmoves] ${PM_CA_BUNDLE_LINE}" >&2
  fi
else
  echo "[minimax-pmoves] WARN: pmoves/scripts/pm-ca-bundle.sh missing -- host TLS not normalized." >&2
fi

# --- NAME BRIDGES (operator-facing alias to upstream SDK name) -------------
# (no name bridges for this CLI)

# --- MCP ROSTER GENERATION ------------------------------------------------
# WHY THIS BLOCK EXISTS. minimax-pmoves does NOT read the tracked
# `.claude/mcp.json` roster that the sibling stacks (claude / kimi / kilo /
# hermes / crush) load -- MiniMax Code reads its OWN `~/.minimax/mcp.json`,
# and that file is RENDERED by pmoves/tools/mcp_config_generator.py from the
# shared inventory plus this client's bootstrap profile.
#
# Nothing else in the launch path rendered it. The launcher sourced
# env.shared and exec'd the binary, so a fresh host -- or any host whose
# ~/.minimax/mcp.json still carried only the `composio` entry -- started the
# client with NO PMOVES MCP servers at all. That is a SILENT degradation: no
# error, no non-zero exit, just a client that cannot reach the fleet. This
# block is what turns the roster from a hope into a precondition.
#
# ORDERING IS LOAD-BEARING.
#   * AFTER env.shared -- the roster expands ${VAR} from the env.shared
#     values (NATS_URL, the cipher token, the cross-node hostnames). A roster
#     rendered before env.shared would carry literal ${VAR} text, which is
#     the exact failure mode claude-pmoves.sh fails closed on.
#   * BEFORE the exec -- the client reads ~/.minimax/mcp.json at startup, so
#     the file has to be current before the binary starts.
#
# --endpoint local: the client is a DESKTOP client on this host, and the
# services it declares node-local are published on THIS host's loopback.
# The generator's "fleet" default would point them at ${TS_Z890} instead.
#
# FAILURE PATH: FAIL CLOSED. If the generator cannot run, the client would
# start with a stale or missing roster and no error at all -- the precise
# failure this block exists to prevent. So a generator failure is an explicit
# ERROR plus a non-zero exit, not a WARN. The operator can still launch
# without the roster by exporting PMOVES_ALLOW_MISSING_ROSTER=1, which is an
# explicit, greppable opt-out rather than a default.
#
# Python discovery is pm-python.sh's ladder (pm_pick_python) -- NOT a bare
# `python3`. The probe argument is `yaml` because mcp_config_generator.py
# reads this client's bootstrap profile, which is YAML.
ROSTER_GEN="$ROOT/pmoves/tools/mcp_config_generator.py"
if [ -n "${PMOVES_ALLOW_MISSING_ROSTER:-}" ]; then
  echo "[minimax-pmoves] PMOVES_ALLOW_MISSING_ROSTER is set -- skipping MCP roster generation." >&2
else
  _roster_why=""
  if [ ! -f "$ROSTER_GEN" ]; then
    _roster_why="the generator is missing: $ROSTER_GEN"
  elif [ ! -f "$ROOT/pmoves/scripts/pm-python.sh" ]; then
    _roster_why="pm-python.sh is missing: $ROOT/pmoves/scripts/pm-python.sh"
  else
    # shellcheck source=../../pmoves/scripts/pm-python.sh
    . "$ROOT/pmoves/scripts/pm-python.sh"
    if ! pm_pick_python yaml 2>/dev/null; then
      _roster_why="no python interpreter that can import yaml (tried \$PMOVES_PYTHON, $ROOT/pmoves/.venv-pmoves, python3, py -3, python)"
    else
      _roster_rc=0
      "${PM_PY[@]}" "$ROSTER_GEN" --client minimax --endpoint local || _roster_rc=$?
      if [ "$_roster_rc" -ne 0 ]; then
        _roster_why="mcp_config_generator.py --client minimax --endpoint local exited $_roster_rc under '${PM_PY[*]}' (its own stderr is above)"
      fi
    fi
  fi
  if [ -n "$_roster_why" ]; then
    echo "[minimax-pmoves] ERROR: could not generate the MCP roster -- $_roster_why" >&2
    echo "[minimax-pmoves]        the client would start with NO PMOVES MCP servers." >&2
    echo "[minimax-pmoves]        to launch anyway: PMOVES_ALLOW_MISSING_ROSTER=1 minimax-pmoves ..." >&2
    exit 1
  fi
  echo "[minimax-pmoves] MCP roster generated for client 'minimax' (endpoint 'local')." >&2
fi

# --- LAUNCH ---------------------------------------------------------------
export PMOVES_LAUNCHER_SESSION="minimax-pmoves.sh"
exec minimax "$@"
